procedure ListOpsTest.map_non_empty_list;
const
  list: TIntArray = (1, 3, 5, 7);
var
  actual: TIntArray;
begin
  actual := TIntListOps.map(list, @PlusOne);
  TapAssertTrue(Self, 'non-empty list', TIntArray([2, 4, 6, 8]), actual);
