// 36549237-f765-4a4c-bfd9-5d3a8f7b07d2
procedure ListOpsTest.foldl_empty_list;
var
  actual: integer;
begin
  actual := TIntListOps.foldl(nil, 2, @Multiply);
  TapAssertTrue(Self, 'empty list', 2, actual);
end;

